const svg=$('#polytopes-svg'), out=$('#polytopes-out'), pick=$('#polytopes-pick');
const W=600,H=360;
// each polygon: counter-clockwise vertex list in lattice coords
const POLY={
  triangle:{ name:'triangle conv{(0,0),(2,0),(0,2)}', verts:[[0,0],[2,0],[0,2]] },
  square:{ name:'square [0,2]^2', verts:[[0,0],[2,0],[2,2],[0,2]] },
  hexagon:{ name:'hexagon', verts:[[1,-1],[2,0],[2,1],[1,2],[0,1],[0,0]] }
};
let cur='triangle';
// map lattice coords -> pixels. origin and unit chosen per-polygon to centre it
function bbox(vs){ let xs=vs.map(v=>v[0]), ys=vs.map(v=>v[1]); return {xmin:Math.min(...xs),xmax:Math.max(...xs),ymin:Math.min(...ys),ymax:Math.max(...ys)}; }
function render(){
  const P=POLY[cur], vs=P.verts; svg.innerHTML='';
  const bb=bbox(vs); const pad=70;
  const spanx=Math.max(1,bb.xmax-bb.xmin), spany=Math.max(1,bb.ymax-bb.ymin);
  const u=Math.min((W-2*pad)/spanx,(H-2*pad)/spany);
  const cx=(bb.xmin+bb.xmax)/2, cy=(bb.ymin+bb.ymax)/2;
  const px=(x)=> W/2 + (x-cx)*u;
  const py=(y)=> H/2 - (y-cy)*u;
  // grid lines
  for(let gx=Math.floor(bb.xmin)-1; gx<=Math.ceil(bb.xmax)+1; gx++){ svg.appendChild(SVG('line',{x1:px(gx),y1:py(bb.ymin-1.5),x2:px(gx),y2:py(bb.ymax+1.5),stroke:'var(--line)','stroke-width':0.7,opacity:0.5})); }
  for(let gy=Math.floor(bb.ymin)-1; gy<=Math.ceil(bb.ymax)+1; gy++){ svg.appendChild(SVG('line',{x1:px(bb.xmin-1.5),y1:py(gy),x2:px(bb.xmax+1.5),y2:py(gy),stroke:'var(--line)','stroke-width':0.7,opacity:0.5})); }
  // filled polygon
  const pts=vs.map(v=>px(v[0])+','+py(v[1])).join(' ');
  svg.appendChild(SVG('polygon',{points:pts,fill:'var(--violet)','fill-opacity':0.18,stroke:'var(--violet)','stroke-width':2}));
  // lattice dots
  for(let gx=Math.floor(bb.xmin)-1; gx<=Math.ceil(bb.xmax)+1; gx++) for(let gy=Math.floor(bb.ymin)-1; gy<=Math.ceil(bb.ymax)+1; gy++){ svg.appendChild(SVG('circle',{cx:px(gx),cy:py(gy),r:1.7,fill:'var(--mute)'})); }
  // vertices
  vs.forEach((v,i)=>{ svg.appendChild(SVG('circle',{cx:px(v[0]),cy:py(v[1]),r:6,fill:'var(--yellow)',stroke:'var(--bg)','stroke-width':1.5}));
    const t=SVG('text',{x:px(v[0])+10,y:py(v[1])-8,'font-size':12,fill:'var(--yellow)'}); t.textContent='('+v[0]+','+v[1]+')'; svg.appendChild(t); });
  // H-representation: for each ccw edge (a->b), inner normal n=(-(by-ay),(bx-ax)); n.x <= n.b
  const ineqs=[];
  const n=vs.length;
  for(let i=0;i<n;i++){ const a=vs[i], b=vs[(i+1)%n]; const dx=b[0]-a[0], dy=b[1]-a[1]; let nx=dy, ny=-dx; // outer normal for ccw
    // reduce by gcd
    function g(p,q){ p=Math.abs(p);q=Math.abs(q); while(q){[p,q]=[q,p%q];} return p||1; }
    const gg=g(nx,ny); nx/=gg; ny/=gg; const rhs=nx*a[0]+ny*a[1];
    const lhs=(nx!==0?(nx===1?'':nx===-1?'-':nx)+'x':'')+(ny!==0?((ny>0&&nx!==0)?' + ':(nx!==0?' - ':(ny===-1?'-':'')))+(Math.abs(ny)===1?'y':Math.abs(ny)+'y'):'');
    ineqs.push((lhs||'0')+' <= '+rhs);
  }
  const cap=SVG('text',{x:20,y:26,'font-size':12,fill:'var(--mute)'}); cap.textContent=P.name+'   yellow = vertices (V-rep)'; svg.appendChild(cap);
  out.textContent =
    'V-representation: conv of '+vs.length+' vertices  '+vs.map(v=>'('+v[0]+','+v[1]+')').join(', ')+'\n'+
    'H-representation ('+ineqs.length+' half-spaces, each an outer-normal inequality):\n  '+ineqs.join('\n  ')+'\n'+
    'f-vector (f0, f1) = ('+vs.length+', '+vs.length+')   '+vs.length+' vertices, '+vs.length+' edges';
}
pick.addEventListener('change',()=>{ cur=pick.value; render(); });
render();

const svg=$('#euler-svg'), out=$('#euler-out'), pick=$('#euler-pick');
const W=600,H=320;
// f-vector data and a small 2D schematic (vertex positions for a wireframe sketch)
const SOL={
  tetra:{ name:'tetrahedron', V:4,E:6,F:4, pts:[[300,60],[180,250],[420,250],[300,180]], edges:[[0,1],[0,2],[0,3],[1,2],[1,3],[2,3]] },
  cube:{ name:'cube', V:8,E:12,F:6, pts:[[200,110],[400,110],[400,250],[200,250],[260,70],[460,70],[460,210],[260,210]], edges:[[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]] },
  octa:{ name:'octahedron', V:6,E:12,F:8, pts:[[300,50],[300,270],[170,160],[430,160],[250,160],[350,160]], edges:[[0,2],[0,3],[0,4],[0,5],[1,2],[1,3],[1,4],[1,5],[2,4],[4,3],[3,5],[5,2]] },
  dodeca:{ name:'dodecahedron', V:20,E:30,F:12, pts:[], edges:[] },
  icosa:{ name:'icosahedron', V:12,E:30,F:20, pts:[], edges:[] }
};
let cur='tetra';
function render(){
  const s=SOL[cur]; svg.innerHTML='';
  // wireframe sketch when we have coordinates
  if(s.pts.length){
    for(const [a,b] of s.edges){ svg.appendChild(SVG('line',{x1:s.pts[a][0],y1:s.pts[a][1],x2:s.pts[b][0],y2:s.pts[b][1],stroke:'var(--violet)','stroke-width':1.6,opacity:0.85})); }
    for(const p of s.pts){ svg.appendChild(SVG('circle',{cx:p[0],cy:p[1],r:5,fill:'var(--yellow)',stroke:'var(--bg)','stroke-width':1.3})); }
  } else {
    const t=SVG('text',{x:300,y:150,'text-anchor':'middle','font-size':16,fill:'var(--mute)'}); t.textContent='('+s.name+' — counts shown below)'; svg.appendChild(t);
  }
  const cap=SVG('text',{x:20,y:26,'font-size':12,fill:'var(--mute)'}); cap.textContent=s.name+'   f-vector (V, E, F) = ('+s.V+', '+s.E+', '+s.F+')'; svg.appendChild(cap);
  // numbers panel
  const labels=[['V (vertices)',s.V,'var(--yellow)'],['E (edges)',s.E,'var(--violet)'],['F (faces)',s.F,'var(--cyan)']];
  labels.forEach((L,i)=>{ const x=120+i*180, y=295; const t=SVG('text',{x,y,'text-anchor':'middle','font-size':14,fill:L[2],'font-weight':700}); t.textContent=L[0]+' = '+L[1]; svg.appendChild(t); });
  const chi=s.V-s.E+s.F;
  out.textContent =
    s.name+':  V = '+s.V+',  E = '+s.E+',  F = '+s.F+'\n'+
    'Euler relation:  V − E + F = '+s.V+' − '+s.E+' + '+s.F+' = '+chi+(chi===2?'  ✓ (= 2, as every 3-polytope must)':'  ✗')+'\n'+
    'this is the d = 3 case of Σ (−1)^i f_i = 1 − (−1)^d = 2.';
}
pick.addEventListener('change',()=>{ cur=pick.value; render(); });
render();

const svg=$('#pick-svg'), out=$('#pick-out');
const spinSl=$('#pick-spin'), spinL=$('#pick-spin-lbl'), resetBtn=$('#pick-reset');
const W=600,H=420;
const GMIN=0, GMAX=8;            // lattice coordinate range shown
const pad=40; const u=(W-2*pad)/(GMAX-GMIN);
const px=(x)=> pad + (x-GMIN)*u;
const py=(y)=> H-pad - (y-GMIN)*u;
const inv=(sx,sy)=>[ Math.round((sx-pad)/u)+GMIN, Math.round((H-pad-sy)/u)+GMIN ];
const PRESETS=[ [[1,1],[6,1],[1,5]], [[2,1],[6,3],[3,6]], [[1,1],[7,2],[2,7]] ];
let verts = PRESETS[0].map(v=>v.slice());
let dragging=-1;
function gcd(a,b){ a=Math.abs(a);b=Math.abs(b); while(b){[a,b]=[b,a%b];} return a; }
function shoelace(vs){ let s=0; for(let i=0;i<vs.length;i++){ const a=vs[i], b=vs[(i+1)%vs.length]; s+=a[0]*b[1]-b[0]*a[1]; } return Math.abs(s)/2; }
function boundaryCount(vs){ let B=0; for(let i=0;i<vs.length;i++){ const a=vs[i], b=vs[(i+1)%vs.length]; B+=gcd(b[0]-a[0], b[1]-a[1]); } return B; }
function pointInOrOn(pt,vs){ // winding / sign test for a simple polygon; returns 'in' | 'on' | 'out'
  const n=vs.length; let onEdge=false;
  for(let i=0;i<n;i++){ const a=vs[i], b=vs[(i+1)%n]; const cross=(b[0]-a[0])*(pt[1]-a[1])-(b[1]-a[1])*(pt[0]-a[0]); const dot=(pt[0]-a[0])*(pt[0]-b[0])+(pt[1]-a[1])*(pt[1]-b[1]); if(cross===0 && dot<=0) onEdge=true; }
  if(onEdge) return 'on';
  // ray cast
  let inside=false; for(let i=0,j=n-1;i<n;j=i++){ const xi=vs[i][0],yi=vs[i][1],xj=vs[j][0],yj=vs[j][1]; const intersect=((yi>pt[1])!==(yj>pt[1])) && (pt[0] < (xj-xi)*(pt[1]-yi)/(yj-yi)+xi); if(intersect) inside=!inside; }
  return inside?'in':'out';
}
function render(){
  svg.innerHTML='';
  spinL.textContent='preset '+(+spinSl.value);
  // grid
  for(let g=GMIN; g<=GMAX; g++){ svg.appendChild(SVG('line',{x1:px(g),y1:py(GMIN),x2:px(g),y2:py(GMAX),stroke:'var(--line)','stroke-width':0.7,opacity:0.5}));
    svg.appendChild(SVG('line',{x1:px(GMIN),y1:py(g),x2:px(GMAX),y2:py(g),stroke:'var(--line)','stroke-width':0.7,opacity:0.5})); }
  // triangle
  const pts=verts.map(v=>px(v[0])+','+py(v[1])).join(' ');
  svg.appendChild(SVG('polygon',{points:pts,fill:'var(--cyan)','fill-opacity':0.16,stroke:'var(--cyan)','stroke-width':2}));
  // classify every lattice point
  let I=0,B=0;
  for(let gx=GMIN; gx<=GMAX; gx++) for(let gy=GMIN; gy<=GMAX; gy++){ const cls=pointInOrOn([gx,gy],verts); let col='var(--mute)', r=1.8;
    if(cls==='in'){ I++; col='var(--green)'; r=4; } else if(cls==='on'){ B++; col='var(--pink)'; r=4; }
    svg.appendChild(SVG('circle',{cx:px(gx),cy:py(gy),r,fill:col})); }
  // vertices (draggable)
  verts.forEach((v,i)=>{ svg.appendChild(SVG('circle',{cx:px(v[0]),cy:py(v[1]),r:8,fill:'var(--yellow)',stroke:'var(--bg)','stroke-width':2,style:'cursor:grab'})); });
  const area=shoelace(verts); const pick=I+B/2-1; const agree=Math.abs(area-pick)<1e-9;
  const cap=SVG('text',{x:20,y:24,'font-size':12,fill:'var(--mute)'}); cap.textContent='drag yellow vertices  ·  green = interior (I)  ·  pink = boundary (B)'; svg.appendChild(cap);
  out.textContent =
    'interior points I = '+I+'    boundary points B = '+B+'\n'+
    'Pick:  I + B/2 − 1 = '+I+' + '+B+'/2 − 1 = '+pick+'\n'+
    'shoelace area = '+area+'    '+(agree?'✓ Pick matches the area':'✗ mismatch');
}
svg.addEventListener('pointerdown',(ev)=>{ const pt=svg.getBoundingClientRect(); const sx=(ev.clientX-pt.left)*W/pt.width, sy=(ev.clientY-pt.top)*H/pt.height;
  let best=-1,bd=1e9; verts.forEach((v,i)=>{ const dd=(px(v[0])-sx)**2+(py(v[1])-sy)**2; if(dd<bd){bd=dd;best=i;} }); if(bd<400){ dragging=best; } });
svg.addEventListener('pointermove',(ev)=>{ if(dragging<0) return; const pt=svg.getBoundingClientRect(); const sx=(ev.clientX-pt.left)*W/pt.width, sy=(ev.clientY-pt.top)*H/pt.height; const g=inv(sx,sy); g[0]=Math.max(GMIN,Math.min(GMAX,g[0])); g[1]=Math.max(GMIN,Math.min(GMAX,g[1]));
  // forbid degenerate / coincident vertices
  if(verts.some((v,i)=>i!==dragging && v[0]===g[0] && v[1]===g[1])) return;
  verts[dragging]=g; if(shoelace(verts)<0.4){ return; } render(); });
svg.addEventListener('pointerup',()=>{ dragging=-1; });
svg.addEventListener('pointerleave',()=>{ dragging=-1; });
spinSl.addEventListener('input',()=>{ verts=PRESETS[+spinSl.value].map(v=>v.slice()); render(); });
resetBtn.addEventListener('click',()=>{ verts=PRESETS[+spinSl.value].map(v=>v.slice()); render(); });
render();

const svg=$('#ehrhart-svg'), out=$('#ehrhart-out'), pick=$('#ehrhart-pick');
const tSl=$('#ehrhart-t'), tL=$('#ehrhart-t-lbl');
const W=600,H=420;
const POLY={
  square:{ name:'unit square', verts:[[0,0],[1,0],[1,1],[0,1]] },
  triangle:{ name:'standard triangle', verts:[[0,0],[1,0],[0,1]] },
  rect:{ name:'rectangle [0,2]x[0,1]', verts:[[0,0],[2,0],[2,1],[0,1]] }
};
let cur='square';
function classify(pt,vs){ const n=vs.length; let onEdge=false;
  function gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){[a,b]=[b,a%b];}return a;}
  for(let i=0;i<n;i++){ const a=vs[i],b=vs[(i+1)%n]; const cross=(b[0]-a[0])*(pt[1]-a[1])-(b[1]-a[1])*(pt[0]-a[0]); const dot=(pt[0]-a[0])*(pt[0]-b[0])+(pt[1]-a[1])*(pt[1]-b[1]); if(cross===0&&dot<=0) onEdge=true; }
  if(onEdge) return 'on';
  let inside=false; for(let i=0,j=n-1;i<n;j=i++){ const xi=vs[i][0],yi=vs[i][1],xj=vs[j][0],yj=vs[j][1]; if(((yi>pt[1])!==(yj>pt[1]))&&(pt[0]<(xj-xi)*(pt[1]-yi)/(yj-yi)+xi)) inside=!inside; }
  return inside?'in':'out';
}
function countLattice(vs,t){ const sv=vs.map(v=>[v[0]*t,v[1]*t]); let xs=sv.map(p=>p[0]),ys=sv.map(p=>p[1]); const x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys); let c=0; for(let gx=x0;gx<=x1;gx++)for(let gy=y0;gy<=y1;gy++){ const cl=classify([gx,gy],sv); if(cl==='in'||cl==='on') c++; } return c; }
function fitQuadratic(pts){ // pts: [[t,y]] for t=0,1,2 -> a t^2 + b t + c
  const [[t0,y0],[t1,y1],[t2,y2]]=pts;
  // t0=0,t1=1,t2=2 assumed
  const c=y0; const a=(y2-2*y1+y0)/2; const b=y1-y0-a; return {a,b,c};
}
function fmtPoly(q){ const a=q.a,b=q.b,c=q.c; function term(co,sym){ if(co===0) return ''; const s=co>0?' + ':' − '; const m=Math.abs(co); return s+(m===1&&sym?'':m)+sym; } let s=(a!==0?(a===1?'':a)+'t²':''); s+=term(b,'t'); s+=term(c,''); s=s.replace(/^ \+ /,''); return s||'0'; }
function render(){
  const P=POLY[cur]; const t=+tSl.value; tL.textContent='t = '+t; svg.innerHTML='';
  const sv=P.verts.map(v=>[v[0]*t,v[1]*t]);
  let xs=sv.map(p=>p[0]),ys=sv.map(p=>p[1]); const x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);
  const GMAX=Math.max(x1,y1,1)+1; const pad=40; const u=(Math.min(W,H-60)-2*pad)/GMAX; const ox=pad, oy=H-60-pad;
  const px=(x)=> ox + x*u, py=(y)=> oy - y*u;
  for(let g=0; g<=GMAX; g++){ svg.appendChild(SVG('line',{x1:px(g),y1:py(0),x2:px(g),y2:py(GMAX),stroke:'var(--line)','stroke-width':0.6,opacity:0.45}));
    svg.appendChild(SVG('line',{x1:px(0),y1:py(g),x2:px(GMAX),y2:py(g),stroke:'var(--line)','stroke-width':0.6,opacity:0.45})); }
  const pts=sv.map(v=>px(v[0])+','+py(v[1])).join(' ');
  svg.appendChild(SVG('polygon',{points:pts,fill:'var(--green)','fill-opacity':0.16,stroke:'var(--green)','stroke-width':2}));
  let cnt=0; for(let gx=x0;gx<=x1;gx++)for(let gy=y0;gy<=y1;gy++){ const cl=classify([gx,gy],sv); if(cl==='in'||cl==='on'){ cnt++; svg.appendChild(SVG('circle',{cx:px(gx),cy:py(gy),r:3.5,fill:'var(--yellow)'})); } }
  const cap=SVG('text',{x:20,y:24,'font-size':12,fill:'var(--mute)'}); cap.textContent=P.name+'  dilated by t='+t+'   yellow = lattice points counted   L_P('+t+') = '+cnt; svg.appendChild(cap);
  // fit polynomial from t=0,1,2 exact counts
  const c0=1; const c1=countLattice(P.verts,1), c2=countLattice(P.verts,2);
  const q=fitQuadratic([[0,c0],[1,c1],[2,c2]]);
  // verify the fit on the current t
  const fitAtT=q.a*t*t+q.b*t+q.c; const ok=Math.abs(fitAtT-cnt)<1e-9;
  function shoelace(vs){ let s=0; for(let i=0;i<vs.length;i++){ const a=vs[i],b=vs[(i+1)%vs.length]; s+=a[0]*b[1]-b[0]*a[1]; } return Math.abs(s)/2; }
  const area=shoelace(P.verts);
  out.textContent =
    'L_P(t) counts lattice points in tP.   L_P(1)='+c1+',  L_P(2)='+c2+',  …\n'+
    'fitted Ehrhart polynomial:  L_P(t) = '+fmtPoly(q)+'\n'+
    'leading coefficient = '+q.a+' = vol(P) = '+area+';   constant term L_P(0) = '+q.c+'  (always 1)\n'+
    'check at t='+t+':  formula gives '+fitAtT+', direct count '+cnt+'   '+(ok?'✓':'✗');
}
pick.addEventListener('change',()=>{ cur=pick.value; render(); });
tSl.addEventListener('input',render);
render();

const svg=$('#reciprocity-svg'), out=$('#reciprocity-out'), pick=$('#reciprocity-pick');
const tSl=$('#reciprocity-t'), tL=$('#reciprocity-t-lbl');
const W=600,H=420;
const POLY={
  square:{ name:'unit square', d:2, verts:[[0,0],[1,0],[1,1],[0,1]], L:(t)=>(t+1)*(t+1), Lint:(t)=>(t-1)*(t-1), Ls:'(t+1)²', Lints:'(t−1)²' },
  triangle:{ name:'standard triangle', d:2, verts:[[0,0],[1,0],[0,1]], L:(t)=>(t+1)*(t+2)/2, Lint:(t)=>(t-1)*(t-2)/2, Ls:'(t+1)(t+2)/2', Lints:'(t−1)(t−2)/2' }
};
let cur='square';
function classify(pt,vs){ const n=vs.length; let onEdge=false;
  for(let i=0;i<n;i++){ const a=vs[i],b=vs[(i+1)%n]; const cross=(b[0]-a[0])*(pt[1]-a[1])-(b[1]-a[1])*(pt[0]-a[0]); const dot=(pt[0]-a[0])*(pt[0]-b[0])+(pt[1]-a[1])*(pt[1]-b[1]); if(cross===0&&dot<=0) onEdge=true; }
  if(onEdge) return 'on';
  let inside=false; for(let i=0,j=n-1;i<n;j=i++){ const xi=vs[i][0],yi=vs[i][1],xj=vs[j][0],yj=vs[j][1]; if(((yi>pt[1])!==(yj>pt[1]))&&(pt[0]<(xj-xi)*(pt[1]-yi)/(yj-yi)+xi)) inside=!inside; }
  return inside?'in':'out';
}
function render(){
  const P=POLY[cur]; const t=+tSl.value; tL.textContent='t = '+t; svg.innerHTML='';
  const sv=P.verts.map(v=>[v[0]*t,v[1]*t]);
  let xs=sv.map(p=>p[0]),ys=sv.map(p=>p[1]); const x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);
  const GMAX=Math.max(x1,y1,1)+1; const pad=40; const u=(Math.min(W,H-60)-2*pad)/GMAX; const ox=pad, oy=H-60-pad;
  const px=(x)=> ox + x*u, py=(y)=> oy - y*u;
  for(let g=0; g<=GMAX; g++){ svg.appendChild(SVG('line',{x1:px(g),y1:py(0),x2:px(g),y2:py(GMAX),stroke:'var(--line)','stroke-width':0.6,opacity:0.45}));
    svg.appendChild(SVG('line',{x1:px(0),y1:py(g),x2:px(GMAX),y2:py(g),stroke:'var(--line)','stroke-width':0.6,opacity:0.45})); }
  const pts=sv.map(v=>px(v[0])+','+py(v[1])).join(' ');
  svg.appendChild(SVG('polygon',{points:pts,fill:'var(--cyan)','fill-opacity':0.14,stroke:'var(--cyan)','stroke-width':2}));
  let inCnt=0,onCnt=0; for(let gx=x0;gx<=x1;gx++)for(let gy=y0;gy<=y1;gy++){ const cl=classify([gx,gy],sv);
    if(cl==='in'){ inCnt++; svg.appendChild(SVG('circle',{cx:px(gx),cy:py(gy),r:4,fill:'var(--green)'})); }
    else if(cl==='on'){ onCnt++; svg.appendChild(SVG('circle',{cx:px(gx),cy:py(gy),r:4,fill:'var(--pink)'})); } }
  const closed=inCnt+onCnt;
  const cap=SVG('text',{x:20,y:24,'font-size':12,fill:'var(--mute)'}); cap.textContent=P.name+', t='+t+'   green = interior   pink = boundary'; svg.appendChild(cap);
  const Lpos=P.L(t); const Lneg=Math.round(Math.pow(-1,P.d)*P.L(-t)); const Lint=P.Lint(t);
  const closedOK=(closed===Lpos), intOK=(inCnt===Lint && Lint===Lneg);
  out.textContent =
    'closed count  L_P(t) = '+P.Ls+' at t='+t+' gives '+Lpos+';   direct all-points count = '+closed+'   '+(closedOK?'✓':'✗')+'\n'+
